from pathlib import Path
from html import escape

root = Path(r'D:/khaled/Cursor')
guide_dir = root / 'docs/guides'
html_path = guide_dir / 'guide-recruteur.html'

pages = [
    ('Menu principal','capture-01-menu-annote.png','Le menu principal est la colonne de navigation de l’espace recruteur. Il donne accès aux fonctions de pilotage, de publication et de suivi.', [('1','Tableau de bord','Résumé d’activité, indicateurs et actions rapides.'),('2','Entreprise','Fiche société, logo, informations publiques et contacts.'),('3','Équipe','Invitation des recruteurs et gestion des permissions.'),('4','Offres','Création, publication, masquage et archivage des annonces.'),('5','ATS','Traitement des candidatures par étape.'),('6','Archives','Historique des candidatures rejetées et offres terminées.')], ['Aider l’utilisateur à se repérer.','Séparer les fonctions importantes.'], ['Cliquer sur une rubrique','Retour accueil public','Déconnexion'], ['Certains menus peuvent dépendre des permissions accordées au recruteur.']),
    ('Tableau de bord','capture-02-dashboard-annote.png','Le tableau de bord donne une vision rapide de l’espace société : profil, offres, candidatures et raccourcis.', [('1','Zone société','Nom de la société et espace courant.'),('2','Créer / traiter','Raccourcis vers publication et ATS.'),('3','Profil entreprise','État de la vitrine employeur.'),('4','Indicateurs','Offres actives, candidatures, dossiers à traiter.'),('5','Actions rapides','Accès direct aux tâches fréquentes.')], ['Comprendre l’activité en quelques secondes.','Lancer rapidement les actions RH.'], ['Créer une offre','Traiter candidatures','Voir profil entreprise','Gérer équipe'], ['Sans société configurée, un message invite à compléter le profil.','Sans droit de publication, le bouton Créer une offre peut disparaître.']),
    ('Profil entreprise','capture-03-entreprise-annote.png','Le profil entreprise est la vitrine employeur. Il doit être complet avant une vraie campagne de recrutement.', [('1','Logo','Affiché sur les offres et la page société.'),('2','Progression','Indique les informations manquantes.'),('3','Champs obligatoires','Nom, ville, pays, e-mail RH, secteur.'),('4','Public / privé','Contrôle la visibilité e-mail/téléphone.'),('5','Enregistrer','Sauvegarde les modifications.')], ['Rassurer les candidats.','Présenter une société crédible.','Centraliser les contacts RH.'], ['Ajouter logo','Basculer Public/Privé','Enregistrer'], ['Consultation seule si le recruteur n’a pas le droit Modifier entreprise.','E-mail privé = non affiché aux candidats.','Profil incomplet = confiance réduite.']),
    ('Gestion de l’équipe','capture-04-equipe-annote.png','La gestion de l’équipe permet de travailler à plusieurs sans donner tous les droits à tout le monde.', [('1','Inviter','Ajoute un recruteur par e-mail.'),('2','Permissions','Droits affichés sous forme de badges.'),('3','Modifier','Change poste, téléphone et permissions.'),('4','Retirer','Supprime l’accès du membre.')], ['Collaborer entre RH et managers.','Limiter les actions sensibles.'], ['Inviter un recruteur','Modifier','Retirer','Envoyer invitation'], ['Seul le responsable peut gérer l’équipe.','Sans droit Publier, impossible de créer une offre.','Sans droit Candidatures, impossible de traiter l’ATS.']),
    ('Gestion des offres','capture-05-offres-annote.png','La page Offres pilote la visibilité des annonces et donne accès aux candidatures de chaque poste.', [('1','Créer une offre','Ouvre le formulaire.'),('2','Filtre statut','Affiche les annonces selon leur état.'),('3','Badge statut','Indique Brouillon, Publiée ou Masquée.'),('4','Actions offre','Modifier, publier, masquer ou archiver.'),('5','Candidatures','Ouvre l’ATS filtré sur l’offre.')], ['Suivre toutes les annonces.','Contrôler ce qui est visible publiquement.'], ['Modifier','Candidatures','Publier','Masquer','Archiver'], ['Brouillon = interne.','Publiée = visible candidats.','Masquée = retirée temporairement.','Expirée = arrêt automatique.']),
    ('Créer ou modifier une offre','capture-06-formulaire-annote.png','Le formulaire doit aider le recruteur à produire une annonce claire, complète et attractive.', [('1','Infos poste','Titre, contrat, mode, lieu, date, salaire.'),('2','Description','Missions, contexte, équipe, responsabilités.'),('3','Profil recherché','Compétences, diplômes et expérience.'),('4','Skills / langues','Mots-clés utiles aux candidats.'),('5','Quiz optionnel','Deux questions de préqualification.'),('6','Publier','Enregistre l’annonce.')], ['Créer une annonce de qualité.','Améliorer la pertinence des candidatures.'], ['Ajouter +','Activer quiz','Configurer quiz','Publier offre','Mettre à jour'], ['Statut Brouillon = non public.','Statut Publiée = visible selon les droits de publication.','Offre expirée = visibilité bloquée.','Quiz optionnel mais utile pour filtrer.']),
    ('ATS - suivi des candidatures','capture-07-ats-annote.png','L’ATS sert à traiter les candidats comme un pipeline. Il permet de suivre chaque candidature depuis la réception jusqu’à la décision.', [('1','Kanban / Liste','Change le mode d’affichage.'),('2','Colonnes','Étapes du recrutement.'),('3','Carte candidat','Résumé du profil.'),('4','Profil','Détail du candidat.'),('5','CV','Ouverture du CV protégé.'),('6','Déplacement','Passage d’une étape à une autre.')], ['Centraliser les candidatures.','Avancer les profils étape par étape.'], ['Profil','CV','Changer étape','Filtrer par offre','Tout afficher'], ['Vue liste recommandée sur mobile.','Rejet = archivage automatique.','Changer étape exige le droit Traiter candidatures.']),
    ('Notifications et archives','capture-08-notifications-archives-annote.png','Les notifications alertent les recruteurs. Les archives gardent l’historique sans encombrer l’espace actif.', [('1','Compteur','Nombre de notifications non lues.'),('2','Notification','Nouvelle candidature ou événement.'),('3','Voir candidatures','Accès direct à l’ATS.'),('4','Résumé archives','Nombre d’éléments archivés.'),('5','Éléments archivés','Candidatures rejetées et offres expirées.')], ['Réagir vite aux nouvelles candidatures.','Conserver un historique propre.'], ['Tout marquer lu','Voir candidature','Voir offre','Restaurer','Supprimer'], ['Candidature rejetée = archive automatique.','Restaurer remet dans le flux si possible.','Supprimer retire de l’historique recruteur.']),
]

cases = [('Profil entreprise incomplet','Message de blocage ou fonctionnalités limitées.','Compléter la fiche Entreprise puis enregistrer.'),('Pas de permission Publier','Bouton Créer/Publier caché ou désactivé.','Demander au responsable société d’ajouter le droit.'),('Pas de permission ATS','Impossible de traiter ou changer les étapes.','Ajouter le droit Traiter candidatures.'),('Offre expirée','L’annonce n’est plus publique automatiquement.','Créer une nouvelle offre ou restaurer si possible.'),('Profil en consultation seule','Les champs entreprise ne sont pas modifiables.','Demander le droit Modifier entreprise au responsable société.'),('Candidature rejetée','Elle sort du pipeline actif et passe dans les archives.','La restaurer depuis Archives si nécessaire.')]
best = ['Compléter la fiche entreprise avant la première annonce.','Utiliser un titre précis : poste + niveau + spécialité.','Indiquer contrat, lieu, télétravail, salaire ou fourchette si possible.','Décrire clairement les missions, l’équipe et les attentes.','Ajouter skills, langues et avantages pour rendre l’offre attractive.','Traiter les candidatures régulièrement dans l’ATS.','Archiver les offres terminées pour garder une interface propre.','Limiter les permissions selon les responsabilités réelles.']

def ul(items): return ''.join(f'<li>{escape(x)}</li>' for x in items)
def keys(items): return ''.join(f'<div class="key"><span>{escape(n)}</span><div><strong>{escape(t)}</strong><p>{escape(b)}</p></div></div>' for n,t,b in items)

toc = ''.join(f'<li>{i}. {escape(title)}</li>' for i, title in enumerate(['Parcours recruteur'] + [p[0] for p in pages] + ['Cas particuliers importants', 'Bonnes pratiques'], 1))
parts = [f'''
<section class="page cover"><div class="cover-card"><p class="kicker">Tun Job</p><h1>Guide recruteur</h1><p>Manuel visuel, clair et professionnel de l’espace société Tun Job.</p></div><img class="cover-img" src="assets-recruteur/capture-02-dashboard-annote.png"><p class="caption">Guide prêt à joindre dans l’e-mail d’invitation recruteur.</p></section>
<section class="page toc"><h2>Sommaire</h2><ol>{toc}</ol></section>
<section class="page compact-page"><div class="split"><div><h2>Parcours recruteur</h2><p>Le recruteur suit un parcours simple : accepter l’invitation, compléter la fiche entreprise, publier une offre, recevoir des candidatures, traiter les profils dans l’ATS, puis archiver les éléments terminés.</p><div class="note"><strong>Logique générale</strong><br>Chaque interface correspond à une étape précise du recrutement. Les boutons visibles dépendent des permissions du recruteur et de l’état de son espace société.</div></div><div class="three"><div><h3>À quoi ça sert</h3><ul>{ul(['Accueillir une société invitée.','Guider le recruteur sans formation technique.','Centraliser offres, candidats et équipe.'])}</ul></div><div><h3>Boutons</h3><ul>{ul(['Créer une offre','Traiter candidatures','Inviter un recruteur','Consulter les archives'])}</ul></div><div><h3>Cas particuliers</h3><ul>{ul(['Profil entreprise manquant = blocage possible.','Permission absente = bouton caché/désactivé.','Offre expirée = visibilité arrêtée automatiquement.'])}</ul></div></div></div></section>''']
for title, image, intro, key_list, purpose, actions, special in pages:
    parts.append(f'<section class="page interface-page"><div class="topline"><h2>{escape(title)}</h2><p>{escape(intro)}</p></div><div class="main-grid"><div class="visual-wrap"><img src="assets-recruteur/{escape(image)}"></div><div class="explain"><div class="keys">{keys(key_list)}</div><div class="three stacked"><div><h3>À quoi ça sert</h3><ul>{ul(purpose)}</ul></div><div><h3>Boutons et actions</h3><ul>{ul(actions)}</ul></div><div><h3>Cas particuliers</h3><ul>{ul(special)}</ul></div></div></div></div></section>')
case_rows = ''.join(f'<tr><td>{escape(a)}</td><td>{escape(b)}</td><td>{escape(c)}</td></tr>' for a,b,c in cases)
best_grid = ''.join(f'<div>{escape(x)}</div>' for x in best)
parts.append(f'<section class="page final-page"><h2>Cas particuliers importants</h2><table class="case-table"><thead><tr><th>Cas</th><th>Ce qui se passe</th><th>Action conseillée</th></tr></thead><tbody>{case_rows}</tbody></table><h2>Bonnes pratiques</h2><div class="best-grid">{best_grid}</div><div class="note support"><strong>Message support recommandé</strong><br>En cas de difficulté, le recruteur peut répondre à l’e-mail d’invitation avec une capture du message affiché. L’administrateur pourra vérifier le profil entreprise, les permissions et l’état des offres.</div></section>')

css = '''@page{size:A4 landscape;margin:9mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,'Segoe UI',sans-serif;color:#0f172a;background:white}.page{width:279mm;height:192mm;page-break-after:always;position:relative;overflow:hidden;padding:11mm 12mm}.page::after{content:'Tun Job - Guide recruteur';position:absolute;left:12mm;bottom:5mm;font-size:9px;color:#64748b}h1,h2,h3,p{margin:0}h1{font-size:42px;line-height:1.05}h2{font-size:25px;line-height:1.1;color:#0f172a;margin-bottom:5px}h3{font-size:12px;color:#1d4ed8;margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em}p{font-size:12px;line-height:1.35;color:#475569}ul{margin:0;padding-left:15px}li{font-size:10.2px;line-height:1.28;margin-bottom:2px;color:#334155}.cover{background:linear-gradient(135deg,#0f172a,#1d4ed8);color:white;display:grid;grid-template-columns:.8fr 1.2fr;gap:12mm;align-items:center}.cover::after{color:#dbeafe}.cover-card{padding:14mm;border-radius:28px;background:rgba(15,23,42,.55);border:1px solid rgba(255,255,255,.18)}.cover-card p{color:#dbeafe;font-size:15px;margin-top:10px}.kicker{color:#93c5fd!important;text-transform:uppercase;letter-spacing:.12em;font-weight:700;font-size:12px!important;margin-bottom:8px!important}.cover-img{width:100%;border-radius:18px;box-shadow:0 18px 45px rgba(0,0,0,.28)}.caption{position:absolute;bottom:12mm;right:12mm;color:#dbeafe!important;font-size:10px!important}.toc h2{font-size:32px;margin-bottom:10mm}.toc ol{columns:2;column-gap:20mm;margin:0;padding-left:0;list-style:none}.toc li{font-size:17px;line-height:1.65;color:#334155;break-inside:avoid}.compact-page .split{display:grid;grid-template-columns:.85fr 1.15fr;gap:10mm;height:100%;align-items:center}.note{margin-top:7mm;padding:8mm;background:#eff6ff;border:1px solid #bfdbfe;border-radius:16px;color:#334155;font-size:12px;line-height:1.35}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:5mm}.three>div{background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:5mm;min-height:36mm}.three>div:nth-child(3){background:#fff7ed;border-color:#fdba74}.interface-page{padding-top:8mm}.topline{display:grid;grid-template-columns:72mm 1fr;gap:8mm;align-items:end;margin-bottom:5mm}.topline p{font-size:11px}.main-grid{display:grid;grid-template-columns:158mm 88mm;gap:7mm;align-items:start}.visual-wrap{background:#eff6ff;border:1px solid #bfdbfe;border-radius:16px;padding:3mm;height:112mm;display:flex;align-items:center;justify-content:center}.visual-wrap img{max-width:100%;max-height:100%;border-radius:12px;display:block}.explain{height:112mm;display:grid;grid-template-rows:auto 1fr;gap:4mm}.keys{display:grid;gap:2mm}.key{display:grid;grid-template-columns:7mm 1fr;gap:2mm;align-items:start}.key span{display:flex;align-items:center;justify-content:center;width:6mm;height:6mm;border-radius:50%;background:#f59e0b;color:white;font-weight:700;font-size:10px}.key strong{font-size:10.5px;color:#0f172a}.key p{font-size:9px;line-height:1.18;color:#64748b}.stacked{grid-template-columns:1fr;gap:2.5mm}.stacked>div{min-height:auto;padding:3.2mm}.stacked li{font-size:8.8px;line-height:1.18}.final-page h2{margin-top:2mm;margin-bottom:4mm}.case-table{width:100%;border-collapse:collapse;margin-bottom:6mm}.case-table th{background:#0f172a;color:white;text-align:left;font-size:11px;padding:7px}.case-table td{border:1px solid #e2e8f0;background:#f8fafc;font-size:10px;line-height:1.28;color:#334155;padding:7px;vertical-align:top}.best-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:3mm}.best-grid div{background:#f0fdf4;border:1px solid #bbf7d0;border-radius:12px;padding:4mm;font-size:10px;line-height:1.25;color:#166534}.support{position:absolute;left:12mm;right:12mm;bottom:12mm;margin:0;background:#eff6ff}'''
html = '<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Guide recruteur - Tun Job</title><style>'+css+'</style></head><body>'+''.join(parts)+'</body></html>'
html_path.write_text(html, encoding='utf-8')
print(html_path)
